#!/usr/bin/env node
// Generate the two documents that must never drift from the built packs:
// references/pack-index.md (what is in each pack, and what is not) and
// assets/libraries/ATTRIBUTION.md (who owns it and under what terms).
//
//   node write-pack-docs.mjs
//
// Both are derived from icon-catalog.json and sources.json, so they are
// regenerated by the build rather than maintained by hand.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const SKILL_ROOT = join(HERE, '..');
const CATALOG = JSON.parse(readFileSync(join(SKILL_ROOT, 'references', 'icon-catalog.json'), 'utf8'));
const MANIFEST = JSON.parse(readFileSync(join(SKILL_ROOT, 'assets', 'libraries', 'sources.json'), 'utf8'));

const PACK_INDEX = join(SKILL_ROOT, 'references', 'pack-index.md');
const ATTRIBUTION = join(SKILL_ROOT, 'assets', 'libraries', 'ATTRIBUTION.md');

const iconsIn = (packId, kind) =>
  CATALOG.icons.filter((i) => i.pack === packId && i.bytes === kind);
const PINNED = CATALOG.icons.filter((i) => i.bytes === 'on-demand' && i.artwork === 'pinned');

// --------------------------------------------------------------- pack index

function packIndex() {
  const out = [];
  out.push('# Icon pack index');
  out.push('');
  out.push('Generated by `scripts/write-pack-docs.mjs`. Do not edit by hand - rebuild the');
  out.push('packs and rerun it.');
  out.push('');
  out.push(`${CATALOG.counts.total} catalogued entries across ${CATALOG.counts.packs} packs: `
    + `${CATALOG.counts.committed} ship their artwork and ${CATALOG.counts.onDemand} are catalogued without it. `
    + `${PINNED.length} of those have a pinned artwork file and a fetch command; the other `
    + `${CATALOG.counts.onDemand - PINNED.length} have nothing a command can download.`);
  out.push('');
  out.push('Search reaches every pack at once. A lower `rank` wins a tie, so a curated pack');
  out.push('always beats the catch-all, and `--context <pack,pack>` tips ties toward the stack');
  out.push('being drawn.');
  out.push('');
  out.push('| Pack | Rank | Icons | On demand (pinned) | About |');
  out.push('|---|---|---|---|---|');
  for (const p of CATALOG.packs) {
    out.push(`| \`${p.id}\` | ${p.rank} | ${p.count} | ${p.onDemand ? `${p.onDemand} (${p.onDemandPinned})` : '-'} | ${p.description} |`);
  }
  out.push('');

  for (const p of CATALOG.packs) {
    out.push(`## ${p.title}`);
    out.push('');
    out.push(`\`${p.id}\` &middot; ${p.count} icons &middot; \`${p.file}\``);
    out.push('');
    if (p.note) { out.push(`> ${p.note}`); out.push(''); }

    if (p.id === 'brands') {
      out.push('Every mark in Simple Icons that no curated pack already owns. Ranked last, and');
      out.push('flagged as a catch-all hit in search results, so a weak match looks weak. There is');
      out.push('no listing here: the pinned version in `sources.json` is the definitive list.');
      out.push('');
      continue;
    }

    const committed = iconsIn(p.id, 'committed');
    if (p.count > 120) {
      out.push(`Too many to list; see the contact sheet at \`assets/libraries/contact-sheets/${p.id}.png\`.`);
      out.push('');
      out.push(`Sample: ${committed.slice(0, 14).map((i) => i.title).join(', ')}, ...`);
    } else {
      out.push(committed.map((i) => i.title).join(' &middot; '));
    }
    out.push('');

    const onDemand = iconsIn(p.id, 'on-demand');
    const pinned = onDemand.filter((i) => i.artwork === 'pinned');
    const unpinned = onDemand.filter((i) => i.artwork !== 'pinned');
    if (onDemand.length) {
      out.push(`**Catalogued without artwork (${onDemand.length}).** No bytes ship for these, and `
        + '`build-diagram` refuses to draw them rather than substituting another product\'s mark.');
      out.push('');
    }
    if (pinned.length) {
      out.push(`*Fetchable with your own permission (${pinned.length}).* The artwork file is pinned, `
        + 'so `find-icon` returns a `fetch-logo` command that downloads it.');
      out.push('');
      out.push('| Product | Why it does not ship | Artwork |');
      out.push('|---|---|---|');
      for (const i of pinned) out.push(`| ${i.title} | ${i.reason} | \`${i.upstreamUrl}\` |`);
      out.push('');
    }
    if (unpinned.length) {
      out.push(`*Nothing to fetch (${unpinned.length}).* No file a command can download is pinned, so `
        + 'these draw as a named placeholder.');
      out.push('');
      out.push('| Product | Why | Brand page |');
      out.push('|---|---|---|');
      for (const i of unpinned) out.push(`| ${i.title} | ${i.reason} | ${i.brandUrl ? `[brand page](${i.brandUrl})` : '-'} |`);
      out.push('');
    }
  }
  return `${out.join('\n')}\n`;
}

// -------------------------------------------------------------- attribution

function attribution() {
  const out = [];
  out.push('# Icon attribution');
  out.push('');
  out.push('Generated by `scripts/write-pack-docs.mjs` from `sources.json`.');
  out.push('');
  out.push('Every icon in these libraries belongs to whoever made it. Arkitect redistributes');
  out.push('them under the terms below and claims no ownership of any of them. **A trademark is');
  out.push('not licensed by the licence on its artwork**: Simple Icons is CC0, but the marks it');
  out.push('draws are still the property of the companies they identify, and are included here');
  out.push('for nominative use - identifying a product in an architecture diagram.');
  out.push('');
  out.push('Two kinds of terms appear below, and the difference matters:');
  out.push('');
  out.push('- **Licence** - a licence grant (CC0, MIT, ISC). Redistribution is permitted on the');
  out.push('  licence terms.');
  out.push('- **Permission** - not a licence. Microsoft, Google and AWS permit their icons to be');
  out.push('  used in architecture diagrams and reserve every other right, including the right to');
  out.push('  withdraw. Icon shape must not be altered, which is why vendor artwork here is');
  out.push('  embedded byte-for-byte with no optimisation pass.');
  out.push('');

  const byLicence = new Map();
  for (const p of CATALOG.packs) {
    for (const i of CATALOG.icons.filter((x) => x.pack === p.id && x.bytes === 'committed')) {
      const key = i.source;
      byLicence.set(key, (byLicence.get(key) ?? 0) + 1);
    }
  }

  out.push('## Sources');
  out.push('');
  out.push('| Source | Terms | Licence | Icons shipped |');
  out.push('|---|---|---|---|');
  for (const [key, src] of Object.entries(MANIFEST.sources)) {
    const name = src.package ? `${src.package}@${src.version}` : key;
    const count = [...byLicence.entries()]
      .filter(([k]) => k === name || k === key)
      .reduce((a, [, n]) => a + n, 0);
    const link = src.licenceUrl ? `[${src.licence}](${src.licenceUrl})` : src.licence;
    out.push(`| ${src.url ? `[${name}](${src.url})` : name} | ${src.terms} | ${link} | ${count || '-'} |`);
  }
  out.push('');

  for (const [key, src] of Object.entries(MANIFEST.sources)) {
    const name = src.package ? `${src.package}@${src.version}` : key;
    out.push(`### ${name}`);
    out.push('');
    if (src.url) {
      out.push(`Downloaded from \`${src.url}\``
        + (src.sha256 ? `, sha256 \`${src.sha256}\`.` : '.'));
      out.push('');
    }
    out.push(`**${src.terms === 'permission' ? 'Permission' : 'Licence'}:** ${src.licence}`
      + `${src.licenceUrl ? ` - <${src.licenceUrl}>` : ''}`);
    if (src.permission) { out.push(''); out.push(src.permission); }
    if (src.note) { out.push(''); out.push(src.note); }
    out.push('');
  }

  out.push('## What is deliberately not here');
  out.push('');
  const onDemand = CATALOG.icons.filter((i) => i.bytes === 'on-demand');
  out.push(`${onDemand.length} products are catalogued with no bytes (${PINNED.length} of them with a pinned artwork file and a fetch command),`);
  out.push('because no permissively licensed mark for them exists, or because the brand owner asked');
  out.push('for it to be removed from the source we would otherwise use. Shipping them anyway would');
  out.push('contradict the reason the rest of this file can be written honestly.');
  out.push('');
  out.push('See `references/pack-index.md` for the full list.');
  out.push('');
  out.push('## Corrections');
  out.push('');
  out.push('If you own one of these marks and want it removed or corrected, open an issue at');
  out.push('<https://github.com/mouadja02/arkitect/issues> and it will be taken out of the next');
  out.push('release. Nothing here is load-bearing enough to argue about.');

  return `${out.join('\n')}\n`;
}

writeFileSync(PACK_INDEX, packIndex());
writeFileSync(ATTRIBUTION, attribution());
console.log(`wrote ${PACK_INDEX}`);
console.log(`wrote ${ATTRIBUTION}`);
